private async Task RestorePreTurnBackupAsync(
    FileSystemManager.CanonicalWriteLease writeLease,
    RollbackSnapshot snapshot)
{
    var validatedBackups = await ReadValidatedRollbackBeforeImagesAsync(writeLease, snapshot);
    var failures = new List<Exception>();
    foreach (var trackedFile in EnumerateRollbackTrackedFiles(writeLease))
    {
        if (snapshot.BaselineFiles.Contains(trackedFile))
            continue;

        try
        {
            if (_fs.FileExists(writeLease, trackedFile))
                _fs.DeleteFile(writeLease, trackedFile);
        }
        catch (Exception ex) when (ex is not CoordinatedStatePublicationUncertainException)
        {
            failures.Add(new IOException(
                $"Failed to delete new canonical file '{trackedFile}' during rollback.",
                ex));
        }
    }

    foreach (var (original, content) in validatedBackups)
    {
        try
        {
            await _fs.WriteFileAtomicBytesAsync(writeLease, original, content);
        }
        catch (Exception ex) when (ex is not CoordinatedStatePublicationUncertainException)
        {
            failures.Add(new IOException(
                $"Failed to restore canonical file '{original}' from rollback evidence.",
                ex));
        }
    }

    if (failures.Count > 0)
    {
        throw new InvalidDataException(
            "Pre-turn rollback could not be completed. Rollback evidence was retained.",
            new AggregateException(failures));
    }
}

private async Task RestorePendingLocalTurnRollbackSnapshotAsync()
{
    var snapshot = _pendingLocalTurnRollbackSnapshot;
    if (snapshot == null)
        return;

    var writeLease = await _fs.AcquireCanonicalWriteLeaseAsync();
    Exception? publicationUncertainty = null;
    try
    {
        if (!snapshot.RestoreCompleted)
        {
            var validatedBackups = new Dictionary<string, byte[]>(StringComparer.OrdinalIgnoreCase);
            foreach (var (originalPath, backupPath) in snapshot.BackupFiles)
            {
                var backupContent = await _fs.ReadFileBytesAsync(writeLease, backupPath)
                    ?? throw new FileNotFoundException("Explorer rollback evidence is missing.", backupPath);
                if (!snapshot.BackupHashes.TryGetValue(originalPath, out var expectedHash) ||
                    !string.Equals(
                        ComputeExplorerRollbackHash(backupContent),
                        expectedHash,
                        StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidDataException(
                        $"Explorer rollback evidence hash mismatch for '{originalPath}'.");
                }

                validatedBackups[originalPath] = backupContent;
            }

            foreach (var trackedFile in snapshot.TrackedFiles)
            {
                if (snapshot.BaselineFiles.Contains(trackedFile))
                    continue;

                if (_fs.FileExists(writeLease, trackedFile))
                    _fs.DeleteFile(writeLease, trackedFile);
            }

            foreach (var (originalPath, backupContent) in validatedBackups)
            {
                await _fs.WriteFileAtomicBytesAsync(writeLease, originalPath, backupContent);
            }

            snapshot.RestoreCompleted = true;
        }

        DiscardPendingLocalTurnRollbackSnapshot(writeLease, snapshot);
        ExplorerLocalTurnRollbackArtifacts.DeleteEmptyDirectories(_fs, writeLease);
    }
    catch (CoordinatedStatePublicationUncertainException failure)
    {
        publicationUncertainty = failure;
        throw;
    }
    finally
    {
        await CoordinatedStateWriteHelper.ReleaseOwnedLeaseAsync(
            _fs, writeLease, completed: false, operationFailure: publicationUncertainty);
    }

    await _stateManager.RefreshGameStateAsync();
}

private async Task RestoreBackupWithLeaseAsync(CanonicalWriteLease lease, string backupFullPath, string originalRelativePath)
{
    EnsureWorkerGeneralMutationAllowed(lease);
    var backup = GetLocalBackupRelativePath(backupFullPath);
    var ordinaryBackup = UsesTrustedLocalWriter(lease, backup);
    var ordinaryTarget = UsesTrustedLocalWriter(lease, originalRelativePath);
    if (ordinaryBackup != ordinaryTarget)
        throw new InvalidOperationException("Backup restoration cannot mix original evidence and ordinary publication.");
    if (!ordinaryBackup) { RestoreBackupCore(backupFullPath, originalRelativePath); return; }
    var target = GetLocalBackupRelativePath(ResolvePath(originalRelativePath));
    var comparison = OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
    if (string.Equals(backup, target, comparison))
        throw new InvalidDataException("Backup and restoration target must be different names.");
    ResolveBackupPublicationRecovery(lease);
    var generation = ReadLocalGenerationSnapshot(lease);
    var bytes = await ReadLocalFileBytesAsync(lease, backup)
        ?? throw new FileNotFoundException("Canonical rollback before-image is missing.", backupFullPath);
    var before = await ReadLocalFileBytesAsync(lease, target);
    await PublishBackupMembersAsync(lease, generation,
        [new(ResolvePath(target), before, bytes), new(ResolvePath(backup), bytes, null)]);

candidate.Revalidate();
_fs.ObserveLoadOperation("PreparedRevalidationBeforeLeaseCompleted");
_fs.ObserveLoadOperation("LeaseAcquisitionStarted");
lifecycleLease = await _fs.AcquireSessionLifecycleLeaseAsync();
writeLease = await _fs.AcquireSessionReplacementWriteLeaseAsync(lifecycleLease, cancellationToken);
_fs.ObserveLoadOperation("LeaseAcquisitionCompleted");
_fs.ResolveBackupPublicationRecovery(writeLease);
if (ensureAdmissionAsync != null) await ensureAdmissionAsync(writeLease);
_fs.ObserveLoadOperation("PreparedRevalidationAfterLeaseStarted");
candidate.Revalidate();
_fs.ObserveLoadOperation("PreparedRevalidationAfterLeaseCompleted");
var generation = _fs.ReadLocalGenerationSnapshot(writeLease);
_fs.ObserveLoadOperation("LiveCaptureStarted");
var live = _fs.CaptureLoadReplacementNamespace(writeLease, candidate.SourcePath);
_fs.ObserveLoadOperation("LiveCaptureCompleted");
var settings = candidate.ArchiveSettings ?? StateManager.PrepareLocalLoadSettings(
    await _fs.ReadLocalFileBytesAsync(writeLease, "config.json"));
_fs.ObserveLoadOperation("PlanCreationStarted");
var namespacePlan = _fs.CreateLoadReplacementNamespacePlan(live, candidate.Images,
    preserveConfiguration: candidate.ArchiveSettings == null);
_fs.ObserveLoadOperation("PlanCreationCompleted");

var replacement = Guid.NewGuid().ToString("N");
var outcome = await _fs.PublishLoadReplacementNamespaceAsync(writeLease, generation, namespacePlan, replacement,
    candidate.Revalidate, cancellationToken);
result = new(outcome.Disposition switch
{
    TrustedLocalPublicationDisposition.Committed => LoadReplacementDisposition.Committed,
    TrustedLocalPublicationDisposition.RolledBack => LoadReplacementDisposition.RolledBack,
    _ => LoadReplacementDisposition.Uncertain
}, candidate.SourcePath,
    outcome.Disposition switch
    {
        TrustedLocalPublicationDisposition.Committed => replacement,
        TrustedLocalPublicationDisposition.RolledBack => generation.Binding.Id,
        _ => null
    },
    outcome.Failure != null || outcome.Disposition == TrustedLocalPublicationDisposition.Uncertain,
    outcome.Failure,
    outcome.Disposition == TrustedLocalPublicationDisposition.Uncertain);

if (result.Disposition == LoadReplacementDisposition.Committed)
{
    // From this point every failure is follow-up to the established replacement.
    _fs.ResolveBackupPublicationRecovery(writeLease);
    if (_hooks?.AfterLoadPublicationValidatedAsync != null)
        await _hooks.AfterLoadPublicationValidatedAsync();
    await _stateManager.RefreshGameStateAsync(writeLease);
    _stateManager.Settings.ApplyLoadedValues(settings);
}

internal async Task<TrustedLocalPublicationOutcome> PublishLoadReplacementNamespaceAsync(CanonicalWriteLease lease,
    LocalSessionGenerationSnapshot expectedGeneration, CanonicalLoadNamespacePlan plan, string replacementGeneration,
    Action validatePreparedNamespace, CancellationToken cancellationToken = default)
{
    if (SessionOperationContext.TryGetExpectedGeneration(BasePath, out _))
        throw new InvalidOperationException("Load cannot run inside a generation-bound session operation.");
    EnsureValidSessionReplacementLease(lease);
    if (lease.MutationIntentRecorder != null || lease.IsLegacyStorageRecovery)
        throw new InvalidOperationException("Ordinary load cannot use a legacy transaction lease.");
    if (!Guid.TryParseExact(replacementGeneration, "N", out var parsed) || parsed.ToString("N") != replacementGeneration)
        throw new InvalidDataException("The replacement generation is invalid.");
    ObserveLoadOperation("MemberMappingStarted");
    var members = plan.Changes.Select(change => new TrustedLocalNamespaceChange(ResolveLoadNamespacePath(change.RelativePath),
        change.Before, change.After)).ToList();
    ObserveLoadOperation("MemberMappingCompleted");
    members.Add(new(SessionGenerationPath,
        expectedGeneration.Bytes == null ? LoadNamespaceMissing : new(TrustedLocalNamespaceKind.File, TrustedLocalFileImage.FromBytes(expectedGeneration.Bytes)),
        new(TrustedLocalNamespaceKind.File, TrustedLocalFileImage.FromBytes(
            JsonSerializer.SerializeToUtf8Bytes(new SessionGenerationDocument(1, replacementGeneration))))));
    var namespacePlan = new TrustedLocalNamespacePlan(GameSessionPath, members, plan.Boundaries);
    var publisher = new TrustedLocalFilePublication(this, new TrustedLocalFileScope([BasePath]));
    void Revalidate()
    {
        ObserveLoadOperation("ManagerRevalidationStarted");
        ResolveBackupPublicationRecovery(lease);
        var generation = ReadLocalGenerationSnapshot(lease);
        if (generation.Binding != expectedGeneration.Binding || !ExactBytesEqual(generation.Bytes, expectedGeneration.Bytes))
            throw new InvalidDataException("The generation changed during namespace preparation.");
        validatePreparedNamespace();
        ObserveLoadOperation("ManagerCandidateRevalidated");
        publisher.ValidateNamespaceBeforePublication(lease, expectedGeneration.Binding, namespacePlan);
        ObserveLoadOperation("ManagerAdmissionCompleted");
    }
    var registrations = new List<InProcessMutationRegistration>();
    try
    {
        Revalidate();
        foreach (var member in members) registrations.Add(new InProcessMutationRegistration(member.Path));
        for (var index = 0; index < plan.Changes.Count; index++)
        {
            var change = plan.Changes[index];
            await InvokeBeforeCanonicalMutationBoundaryAsync(change.RelativePath);
            if (ResolveLoadNamespacePath(change.RelativePath) != members[index].Path)
                throw new InvalidDataException("Canonical namespace identity changed before mutation.");
            await InvokeAfterCanonicalMutationBoundaryValidatedAsync(change.RelativePath);
        }
        for (var attempt = 0; ; attempt++)
        {
            cancellationToken.ThrowIfCancellationRequested();
            Revalidate();
            var outcome = publisher.PublishNamespaceWithOutcome(lease, expectedGeneration.Binding, namespacePlan, _hooks?.LocalPublicationObserver);
            if (outcome.Disposition == TrustedLocalPublicationDisposition.Committed)
                CanonicalRootAuthorityIdentity.AdvanceSessionGenerationRevision();
            if (outcome.Disposition != TrustedLocalPublicationDisposition.RolledBack || outcome.Failure is InvalidDataException ||
                outcome.Failure == null || !IsTransientFileAccessException(outcome.Failure) || attempt >= TransientFileAccessRetryCount - 1)
                return outcome;
            await Task.Delay(TransientFileAccessRetryDelay, cancellationToken);
        }
    }
    finally { foreach (var registration in registrations) registration.Dispose(); }

private async Task<string> PublishSessionReplacementAsync(CanonicalWriteLease lease, bool clearGameState)
{
    EnsureValidSessionReplacementLease(lease);
    VerifyCurrentSessionOperation(lease);
    if (lease.MutationIntentRecorder != null || lease.IsLegacyStorageRecovery)
        throw new InvalidOperationException("Common session replacement cannot run inside a legacy transaction.");
    // Clear consumes a current pending turn only after its original signed
    // authority validates every retained before-image. Rotation alone cannot.
    EnsureNoLegacyStorageEvidence(currentPendingClear: clearGameState ? lease : null);

    var scope = new TrustedLocalFileScope([BasePath]);
    var generation = ReadLocalGenerationSnapshot(lease);
    var selected = new HashSet<string>(StringComparer.Ordinal);
    void AddTree(string relative, Func<string, bool>? exclude = null, bool jsonOnly = false)
    {
        foreach (var file in EnumerateLocalTreeFiles(scope, Path.Combine(GameSessionPath, relative), exclude, jsonOnly))
            selected.Add(file);
    }
    if (clearGameState)
    {
        scope.ValidateFile(Path.Combine(GameSessionPath,
            LocalUiSessionLockService.LockPath.Replace('/', Path.DirectorySeparatorChar)));
        // Directory creation can leave harmless structure on failure, but a
        // wrong-type required path must fail before publishing any file.
        foreach (var directory in RequiredDirectories)
            scope.ValidateDirectory(Path.Combine(BasePath, directory.Replace('/', Path.DirectorySeparatorChar)));
        AddTree("input", jsonOnly: true);
        AddTree("output", jsonOnly: true);
        AddTree("ready", jsonOnly: true);
        var gameState = Path.Combine(GameSessionPath, "game_state");
        AddTree("game_state", entry => ShouldPreserveAcrossGameStateClear(gameState, entry));
        AddTree("lore");
        AddTree("stories");
    }
    AddTree("worker_tasks");
    AddTree("worker_proposals");
    if (!clearGameState)
    {
        foreach (var relative in new[] { "game_state/control/gm_worker_latest_validation_repair_task.json",
                     "game_state/control/validation_repair_ready.json" })
        {
            var path = scope.ValidateFile(Path.Combine(GameSessionPath, relative.Replace('/', Path.DirectorySeparatorChar)));
            if (File.Exists(path)) selected.Add(path);
        }
    }

    // Capture every before image before the single generation/member decision.
    var changes = new List<TrustedLocalFileChange>();
    foreach (var path in selected.OrderBy(path => path, StringComparer.Ordinal))
    {
        var relative = GetLocalRelativePath(GameSessionPath, path, OperatingSystem.IsWindows());
        var bytes = await ReadLocalFileBytesAsync(lease, relative)
            ?? throw new InvalidDataException("A selected session file disappeared during replacement preparation.");
        // Keep the manager's root spelling at its existing mutation/lease boundaries.
        changes.Add(new(ResolvePath(relative), bytes, null));
    }
    var replacement = Guid.NewGuid().ToString("N");
    changes.Add(new(SessionGenerationPath, generation.Bytes,
        JsonSerializer.SerializeToUtf8Bytes(new SessionGenerationDocument(1, replacement))));
    if (clearGameState)
        foreach (var directory in RequiredDirectories)
            scope.EnsureDirectory(Path.Combine(BasePath, directory.Replace('/', Path.DirectorySeparatorChar)));

    var outcome = await PublishLocalCoreAsync(lease, generation.Binding, changes, CancellationToken.None);
    RequireCommittedLocalPublication(outcome);
    CanonicalRootAuthorityIdentity.AdvanceSessionGenerationRevision();
    return replacement;

// A task/cleanup lease is an operation capability, never a general canonical
// writer. Check at participating mutation entrypoints before preparation.
internal void EnsureWorkerGeneralMutationAllowed(CanonicalWriteLease lease)
{
    EnsureValidCanonicalWriteLease(lease);
    EnsureMainMutationAllowed(lease);
    if (IsWorkerCleanupAudit(lease) || lease.WorkerPurpose?.Dispatch != null)
        throw new InvalidOperationException("Original worker purpose cannot perform this canonical mutation.");
}

private void EnsureWorkerAuditAppend(CanonicalWriteLease lease, string path, ReadOnlySpan<byte> suffix)
{
    if (lease.WorkerPurpose?.Dispatch != null)
        throw new InvalidOperationException("Task admission cannot append canonical bytes.");
    if (!IsWorkerCleanupAudit(lease)) return;
    EnsureWorkerRecoveryAdmission(lease,"worker-cleanup-audit-append");
    if (lease.MutationIntentRecorder != null || lease.IsLegacyStorageRecovery ||
        !string.Equals(path, GmWorkerAuditLog.AuditLogPath, StringComparison.Ordinal))
        throw new InvalidOperationException("Cleanup audit requires its exact ordinary audit path.");
    lease.WorkerPurpose!.Execution.ValidateCleanupAppend(lease.WorkerPurpose, suffix);
}

internal void EnsureWorkerPurposePublication(CanonicalWriteLease lease, TrustedLocalGeneration generation,
    IReadOnlyList<TrustedLocalFileChange> changes)
{
    EnsureMainMutationAllowed(lease);
    if (lease.WorkerPurpose?.Dispatch is { } dispatch)
    {
        EnsureWorkerRecoveryAdmission(lease,"worker-task-reservation");
        if (changes.Count != 1 || generation != TrustedLocalGeneration.Existing(dispatch.GenerationId))
            throw new InvalidOperationException("Task reservation cannot publish another member or generation.");
        var relative = GetLocalRelativePath(GameSessionPath, changes[0].Path, OperatingSystem.IsWindows());
        dispatch.ValidateReservation(this, lease, relative, changes[0].Before, changes[0].After);
        return;
    }
    if (!IsWorkerCleanupAudit(lease)) return;
    EnsureWorkerRecoveryAdmission(lease,"worker-cleanup-audit-publication");
    var purpose = lease.WorkerPurpose!;
    if (changes.Count != 1 || generation != TrustedLocalGeneration.Existing(purpose.Execution.Identity.GenerationId))
        throw new InvalidOperationException("Cleanup audit cannot publish another member or generation.");
    var change = changes[0];
    var comparison = OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
    if (!string.Equals(Path.GetFullPath(change.Path), ResolvePath(GmWorkerAuditLog.AuditLogPath), comparison))
        throw new InvalidOperationException("Cleanup publication is outside the original audit path.");
    var prefix = change.Before ?? Encoding.UTF8.GetPreamble();
    if (change.After == null || change.After.Length < prefix.Length ||
        !change.After.AsSpan(0, prefix.Length).SequenceEqual(prefix))
        throw new InvalidOperationException("Cleanup audit must preserve every original prefix byte.");
    EnsureWorkerAuditAppend(lease, GmWorkerAuditLog.AuditLogPath, change.After.AsSpan(prefix.Length));

